// 각 뽑기마다 ~5% 확률로 배경화면 1개 추가 지급
const WP_DROP_CHANCE = 0.05; // 5%
const WP_POOL = [
  // R등급 (각 1.25%씩 → 합 5%)
  { id: 'wp_neon_city',    grade: 'R',  weight: 2 },
  { id: 'wp_pixel_forest', grade: 'R',  weight: 2 },
  { id: 'wp_static_noise', grade: 'R',  weight: 2 },
  { id: 'wp_cyber_grid',   grade: 'R',  weight: 2 },
  // SR등급 (각 약 0.8%)
  { id: 'wp_aurora',       grade: 'SR', weight: 0.6 },
  { id: 'wp_cosmos',       grade: 'SR', weight: 0.6 },
  // UR등급 (약 0.1%)
  { id: 'wp_matrix',       grade: 'UR', weight: 0.1 },
];

function pullWallpaper(): { id: string; grade: string } {
  const total = WP_POOL.reduce((s, w) => s + w.weight, 0);
  let r = Math.random() * total;
  for (const w of WP_POOL) {
    r -= w.weight;
    if (r <= 0) return { id: w.id, grade: w.grade };
  }
  return { id: WP_POOL[0].id, grade: WP_POOL[0].grade };
}

// ── 뽑기 풀 정의 ────────────────────────────────────────────────────────
// R 80% (10종 균등 배분), SR 19.3% (6종 균등 배분), UR 0.7% (2종 균등 배분)
const SR_W  = 19.3 / 6;   // ≈ 3.217%
