    }

    // ── 2. 캐릭터 + 배경화면 결정 ────────────────────────────────────
    const pulls = Array.from({ length: count }, () => pullOne());

    const ownedSet = new Set((owned ?? []).map((r: { character_id: string }) => r.character_id));
    const ownedWpSet = new Set((ownedWp ?? []).map((r: { wallpaper_id: string }) => r.wallpaper_id));

    const characters = pulls.map(p => ({
      id: p.id,
      grade: p.grade,
      isNew: !ownedSet.has(p.id),
    }));

    // 각 pull마다 5% 확률로 배경화면 추가 지급
    const wallpaperDrops: { id: string; grade: string; isNew: boolean }[] = [];
    for (let i = 0; i < count; i++) {
      if (Math.random() < WP_DROP_CHANCE) {
        const wp = pullWallpaper();
        wallpaperDrops.push({ id: wp.id, grade: wp.grade, isNew: !ownedWpSet.has(wp.id) });
        ownedWpSet.add(wp.id); // 같은 pull에서 중복 방지
      }
    }
    // 동일 배경화면 중복 제거 (isNew는 첫 등장 기준)
    const seenWp = new Map<string, { id: string; grade: string; isNew: boolean }>();
    for (const wp of wallpaperDrops) {
      if (!seenWp.has(wp.id)) seenWp.set(wp.id, wp);
    }
