    this.add.rectangle(363, 28, 88, 30, 0x000000, 0.6)
      .setInteractive()
      .on('pointerdown', onClick);
    const txt = this.add.text(363, 28, 'SKIP  ▶▶', {
      fontSize: '12px', color: '#777777', fontFamily: 'monospace',
    }).setOrigin(0.5).setInteractive({ useHandCursor: true });
