const GAP_Y = 10;
const GRID_LEFT = (400 - (COLS * CARD_W + (COLS - 1) * GAP_X)) / 2; // 35px
const GRID_TOP = 105;

// ── 배경화면 그리드 설정 ────────────────────────────────────────────────────
const WP_COLS = 2;
const WP_CARD_W = 170;
const WP_CARD_H = 110;
const WP_GAP_X = 20;
const WP_GAP_Y = 12;
const WP_GRID_LEFT = (400 - (WP_COLS * WP_CARD_W + (WP_COLS - 1) * WP_GAP_X)) / 2; // 10px
const WP_GRID_TOP = 105;

// ── 스크롤 영역 (헤더 아래 ~ 하단 버튼 위) ─────────────────────────────────
const SCROLL_TOP = 95;
const SCROLL_BOTTOM = 548;

