    fontSize: '11px', color: '#888888', fontFamily: 'monospace',
  }).setOrigin(0.5);

  const wpCardW = 58, wpCardH = 36, wpGapX = 10;
  const wpTotalW = this.wpResults.length * wpCardW + (this.wpResults.length - 1) * wpGapX;
  const wpStartX = (400 - wpTotalW) / 2 + wpCardW / 2;

  this.wpResults.forEach((wp, i) => {
    const def = WALLPAPERS.find(w => w.id === wp.id);
    const x = wpStartX + i * (wpCardW + wpGapX);
    const y = wpStartY + wpCardH / 2;

    const bg = this.add.rectangle(x, y, wpCardW, wpCardH, 0x111122)
      .setStrokeStyle(1.5, WP_ACCENT_INT).setAlpha(0);

    if (def && this.textures.exists(def.bgKey)) {
      const thumb = this.add.image(x, y, def.bgKey)
        .setDisplaySize(wpCardW - 4, wpCardH - 4).setAlpha(0);
      this.tweens.add({ targets: thumb, alpha: 1, duration: 200, delay: i * 80 });
    }

    const nm = this.add.text(x, y + wpCardH / 2 - 9, def?.name ?? wp.id, {
      fontSize: '8px', color: WP_ACCENT_HEX,
      stroke: '#000000', strokeThickness: 2,
    }).setOrigin(0.5).setAlpha(0);

    if (wp.isNew) {
      this.add.text(x + wpCardW / 2, y - wpCardH / 2 + 1, 'NEW', {
        fontSize: '7px', color: '#ffff00', backgroundColor: '#aa0000',
        padding: { x: 1, y: 1 },
      }).setOrigin(1, 0).setAlpha(0);
    }

    this.tweens.add({ targets: [bg, nm], alpha: 1, duration: 200, delay: i * 80 });
  });

  wpSectionBottom = wpStartY + wpCardH + 10;
}

// 잔여 SKOR
const skorY = wpSectionBottom > 0 ? wpSectionBottom + 16 : (total > 5 ? 350 : 340);

