   865→        awakeBonusLines.push(`★1 각성: 이동속도 +${spd} px/s`);
   866→      }
   867→      if (awakeLevel >= 2) {
   868→        if (def.id === 'maehwa') {
   869→          awakeBonusLines.push('★2 각성: 특수 똥 수집 시 +5점');
   870→        } else {
   871→          const spd = def.grade === 'UR' ? 20 : def.grade === 'SR' ? 15 : 10;
