/** 현재 탭에 맞게 배경 이미지 업데이트 */
private updateBgForTab() {
  if (this.activeTab === 'character') {
    const def = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
    this.bgImage.setTexture(def.illustKey).setAlpha(1).clearTint();
  } else {
