   110→// ── localStorage 서명 (djb2, character.ts 패턴과 동일) ──────────────────────
   111→
   112→const OWNED_WP_KEY     = 'ownedWallpapers';
   113→const OWNED_WP_SIG_KEY = 'ownedWallpapersSig';
   114→const SELECTED_WP_KEY  = 'selectedWallpaper';
   115→const _WP_SALT         = 'ddong-wp-\u0076\u0031';
   116→
   117→function _signWpList(list: string[]): string {
   118→  const str = [...list].sort().join(',') + _WP_SALT;
   119→  let h = 5381;
   120→  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
   121→  return h.toString(36);
   122→}
   123→
   124→function _saveOwnedWp(list: string[]): void {
   125→  localStorage.setItem(OWNED_WP_KEY, JSON.stringify(list));
   126→  localStorage.setItem(OWNED_WP_SIG_KEY, _signWpList(list));
   127→}
   128→
   129→/** 보유 배경화면 목록 반환. 서명 불일치 시 변조로 판단하여 빈 배열로 초기화. */
   130→export function getOwnedWallpapers(): string[] {
   131→  try {
   132→    const raw = localStorage.getItem(OWNED_WP_KEY);
   133→    const sig = localStorage.getItem(OWNED_WP_SIG_KEY);
   134→    const list: string[] = raw ? JSON.parse(raw) : [];
   135→
   136→    if (sig === null) {
   137→      // 서명 미존재 → 기존 데이터 마이그레이션: 신뢰 후 서명 최초 발급
   138→      _saveOwnedWp(list);
   139→      return list;
   140→    }
   141→
   142→    // 서명 불일치 → 변조로 판단, 빈 배열로 초기화
   143→    if (sig !== _signWpList(list)) {
   144→      _saveOwnedWp([]);
   145→      return [];
   146→    }
   147→
   148→    return list;
   149→  } catch {
   150→    return [];
   151→  }
   152→}
   153→
   154→/** 서버 동기화 등 외부에서 목록 전체를 덮어쓸 때 사용 (서명 함께 갱신) */
   155→export function setOwnedWallpapers(list: string[]): void {
   156→  _saveOwnedWp(list);
   157→}
   158→
   159→/** 배경화면을 보유 목록에 추가 (가챠 완료 직후 호출) */
   160→export function addOwnedWallpaper(id: string): void {
   161→  const owned = getOwnedWallpapers();
   162→  if (!owned.includes(id)) {
   163→    owned.push(id);
   164→    _saveOwnedWp(owned);
   165→  }
   166→}
   167→
   168→/** 선택된 배경화면 ID 반환. 없으면 null (기본 배경 사용). */
   169→export function getSelectedWallpaper(): string | null {
