   172→
   173→/** 배경화면 선택 저장. null 전달 시 선택 해제. */
   174→export function setSelectedWallpaper(id: string | null): void {
   175→  if (id === null) {
   176→    localStorage.removeItem(SELECTED_WP_KEY);
   177→  } else {
   178→    localStorage.setItem(SELECTED_WP_KEY, id);
   179→  }
   180→}
