   182→/**
   183→ * 보유 목록과 교차 검증하여 안전한 배경화면 ID 반환.
   184→ * 미보유 배경이 선택되어 있으면 null로 강제 초기화 (변조 방지).
   185→ */
   186→export function getSafeSelectedWallpaper(): string | null {
   187→  const selected = getSelectedWallpaper();
   188→  if (!selected) return null;
   189→  const owned = getOwnedWallpapers();
   190→  if (owned.includes(selected)) return selected;
   191→  // 변조 감지 → null로 강제 초기화
   192→  setSelectedWallpaper(null);
   193→  return null;
   194→}
   195→
   196→/** 배경화면 정의 조회. 없으면 undefined. */
   197→export function getWallpaperDef(id: string): BackgroundDef | undefined {
   198→  return WALLPAPERS.find(w => w.id === id);
   199→}
