   271→  private getDifficultyEmoji(difficulty: string): string {
   272→    switch (difficulty) {
   273→      case 'normal': return '😐';
   274→      case 'hard': return '😰';
   275→      case 'extreme': return '💀';
   276→      default: return '🎮';
   277→    }
   278→  }
