   280→  private getSpeedText(baseSpeed: number): string {
   281→    if (baseSpeed <= 150) return '느림';
   282→    if (baseSpeed <= 175) return '보통';
   283→    if (baseSpeed <= 200) return '빠름';
   284→    return '매우 빠름';
   285→  }
   286→
   287→  private lightenColor(color: number): number {
   288→    const r = Math.min(255, ((color >> 16) & 0xFF) + 30);
   289→    const g = Math.min(255, ((color >> 8) & 0xFF) + 30);
   290→    const b = Math.min(255, (color & 0xFF) + 30);
   291→    return (r << 16) | (g << 8) | b;
   292→  }
   293→
   294→  private startGame(difficulty: Difficulty) {
   295→    this.scene.start('GameScene', {
   296→      gameMode: this.gameMode,
   297→      difficulty: difficulty
   298→    });
   299→  }
