   183→      fontSize: '14px', color: '#ffffff', fontStyle: 'bold',
   184→    }).setOrigin(0.5);
   185→
   186→    this.wpTabBtnBg = this.add.rectangle(290, TAB_Y, TAB_W, TAB_H, 0x222222)
   187→      .setStrokeStyle(1.5, 0x555555)
   188→      .setInteractive({ useHandCursor: true });
   189→    this.wpTabLabel = this.add.text(290, TAB_Y, '배경화면', {
   190→      fontSize: '14px', color: '#888888', fontStyle: 'bold',
   191→    }).setOrigin(0.5);
   192→
   193→    this.charTabBtnBg.on('pointerup', () => {
   194→      if (this.detailPanel) return;
   195→      this.switchTab('character');
   196→    });
   197→    this.wpTabBtnBg.on('pointerup', () => {
   198→      if (this.detailPanel) return;
   199→      this.switchTab('wallpaper');
   200→    });
   201→
   202→    // 구분선
   203→    this.add.rectangle(200, 80, 380, 1, 0x444444);
   204→
   205→    // 현재 선택 상태 표시
   206→    this.headerNameText = this.add.text(200, 88, `현재: ${selectedDef.name}`, {
   207→      fontSize: '13px',
   208→      color: selectedDef.gradeColor,
   209→      stroke: '#000',
   210→      strokeThickness: 3,
   211→    }).setOrigin(0.5);
   212→
   213→    // ── 스크롤 가능한 카드 컨테이너 ─────────────────────────────────────
   214→    this.cardsContainer = this.add.container(0, 0);
   215→
   216→    this.buildCharacterGrid();
   217→
   218→    // 스크롤 최대 범위 계산 (buildCharacterGrid 내부에서도 설정되지만 여기서도 초기화)
   219→    const totalRows = Math.ceil(CHARACTERS.length / COLS);
   220→    const contentBottom = GRID_TOP + (totalRows - 1) * (CARD_H + GAP_Y) + CARD_H + 10;
   221→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   222→
   223→    // 카드 영역 마스크 (스크롤 영역 밖 숨김)
   224→    // this.make: display list에 추가되지 않으므로 shutdown 시 직접 정리 필요
   225→    this.maskGfx = this.make.graphics({ x: 0, y: 0 });
   226→    this.maskGfx.fillStyle(0xffffff);
   227→    this.maskGfx.fillRect(0, SCROLL_TOP, 400, SCROLL_BOTTOM - SCROLL_TOP);
   228→    this.cardsContainer.setMask(this.maskGfx.createGeometryMask());
   229→
   230→    // ── 드래그 스크롤 입력 ───────────────────────────────────────────────
   231→    this.input.on('pointerdown', (p: Phaser.Input.Pointer) => {
   232→      this.hasPointerDownInScene = true;
   233→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   234→      if (p.y < SCROLL_TOP || p.y > SCROLL_BOTTOM) return;
   235→      this.pointerDownY = p.y;
   236→      this.pointerDownScrollY = this.scrollOffset;
   237→      this.hasDragged = false;
   238→    });
   239→
   240→    this.input.on('pointermove', (p: Phaser.Input.Pointer) => {
   241→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   242→      if (!p.isDown) return;
   243→      const dy = this.pointerDownY - p.y;
   244→      if (Math.abs(dy) > 5) {
   245→        this.hasDragged = true;
   246→        this.scrollOffset = Phaser.Math.Clamp(
   247→          this.pointerDownScrollY + dy,
   248→          0,
   249→          this.maxScrollOffset,
   250→        );
   251→        this.cardsContainer.setY(-this.scrollOffset);
   252→      }
   253→    });
   254→
   255→    this.input.on('pointerup', () => {
   256→      if (this.detailPanel) return; // 상세 패널 열려있으면 hasDragged 초기화 무시
   257→      // card pointerup 이벤트가 먼저 발생하므로 다음 프레임에 초기화
   258→      this.time.delayedCall(0, () => {
   259→        this.hasDragged = false;
   260→        this.hasPointerDownInScene = false;
   261→      });
   262→    });
   263→
   264→    // 마우스 휠
   265→    this.input.on(
   266→      'wheel',
   267→      (_p: Phaser.Input.Pointer, _go: unknown[], _dx: number, deltaY: number) => {
   268→        if (this.detailPanel) return; // 상세 패널 열려있으면 휠 스크롤 무시
   269→        this.scrollOffset = Phaser.Math.Clamp(
   270→          this.scrollOffset + deltaY * 0.5,
   271→          0,
   272→          this.maxScrollOffset,
   273→        );
   274→        this.cardsContainer.setY(-this.scrollOffset);
   275→      },
   276→    );
   277→
   278→    // ── 고정 UI ─────────────────────────────────────────────────────────
   279→    this.createBackButton();
   280→
   281→    // maskGfx는 display list 외부에 있으므로 씬 종료 시 직접 정리
   282→    this.events.once('shutdown', () => { this.maskGfx.destroy(); });
   283→  }
