   285→  // ── 그리드 빌더 ─────────────────────────────────────────────────────────
   286→
   287→  private buildCharacterGrid() {
   288→    this.cardHighlights.clear();
   289→    this.coresGfx = this.add.graphics();
   290→    CHARACTERS.forEach((char, index) => {
   291→      const col = index % COLS;
   292→      const row = Math.floor(index / COLS);
   293→      const x = GRID_LEFT + col * (CARD_W + GAP_X) + CARD_W / 2;
   294→      const y = GRID_TOP + row * (CARD_H + GAP_Y) + CARD_H / 2;
   295→      this.createCharacterCard(char, x, y);
   296→    });
   297→    this.cardsContainer.add(this.coresGfx);
   298→
   299→    const totalRows = Math.ceil(CHARACTERS.length / COLS);
   300→    const contentBottom = GRID_TOP + (totalRows - 1) * (CARD_H + GAP_Y) + CARD_H + 10;
   301→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   302→  }
   303→
   304→  private buildWallpaperGrid() {
   305→    this.wpHighlights.clear();
   306→    this.ownedWpIds = getOwnedWallpapers();
   307→    this.selectedWpId = getSelectedWallpaper();
   308→
   309→    const availableWps = WALLPAPERS.filter(w => AVAILABLE_WP_IDS.includes(w.id));
   310→    availableWps.forEach((wp, index) => {
   311→      const col = index % WP_COLS;
   312→      const row = Math.floor(index / WP_COLS);
   313→      const x = WP_GRID_LEFT + col * (WP_CARD_W + WP_GAP_X) + WP_CARD_W / 2;
   314→      const y = WP_GRID_TOP + row * (WP_CARD_H + WP_GAP_Y) + WP_CARD_H / 2;
   315→      this.createWallpaperCard(wp, x, y);
   316→    });
   317→
   318→    const totalRows = Math.ceil(availableWps.length / WP_COLS);
   319→    const contentBottom = WP_GRID_TOP + (totalRows - 1) * (WP_CARD_H + WP_GAP_Y) + WP_CARD_H + 10;
   320→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   321→  }
   322→
   323→  private switchTab(tab: 'character' | 'wallpaper') {
   324→    if (this.activeTab === tab) return;
   325→    this.activeTab = tab;
   326→    this.scrollOffset = 0;
   327→    this.hasDragged = false;
   328→    this.cardsContainer.setY(0);
   329→    this.updateBgForTab();
   330→
   331→    // 컨테이너 내 카드 오브젝트 전부 제거
   332→    this.cardsContainer.removeAll(true);
   333→    this.cardHighlights.clear();
   334→    this.wpHighlights.clear();
   335→
   336→    // 탭 버튼 스타일 갱신
   337→    if (tab === 'character') {
   338→      this.charTabBtnBg.setFillStyle(0x1144bb).setStrokeStyle(1.5, 0x4488ff);
   339→      this.charTabLabel.setColor('#ffffff');
   340→      this.wpTabBtnBg.setFillStyle(0x222222).setStrokeStyle(1.5, 0x555555);
   341→      this.wpTabLabel.setColor('#888888');
   342→
   343→      this.buildCharacterGrid();
   344→
   345→      // 헤더 텍스트 갱신
   346→      const def = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
   347→      this.headerNameText.setText(`현재: ${def.name}`).setColor(def.gradeColor);
   348→    } else {
   349→      this.wpTabBtnBg.setFillStyle(0x1144bb).setStrokeStyle(1.5, 0x4488ff);
   350→      this.wpTabLabel.setColor('#ffffff');
   351→      this.charTabBtnBg.setFillStyle(0x222222).setStrokeStyle(1.5, 0x555555);
   352→      this.charTabLabel.setColor('#888888');
   353→
   354→      this.buildWallpaperGrid();
   355→
   356→      // 헤더 텍스트 갱신
   357→      const selWpDef = this.selectedWpId
   358→        ? WALLPAPERS.find(w => w.id === this.selectedWpId)
   359→        : null;
   360→      this.headerNameText
   361→        .setText(`배경: ${selWpDef?.name ?? '기본'}`)
   362→        .setColor(this.selectedWpId ? WP_ACCENT_HEX : '#888888');
   363→    }
   364→  }
