   366→  /** 현재 탭에 맞게 배경 이미지 업데이트 */
   367→  private updateBgForTab() {
   368→    if (this.activeTab === 'character') {
   369→      const def = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
   370→      this.bgImage.setTexture(def.illustKey).setDisplaySize(400, 600).setAlpha(1).clearTint();
   371→    } else {
   372→      const wpDef = this.selectedWpId
   373→        ? WALLPAPERS.find(w => w.id === this.selectedWpId)
   374→        : null;
   375→      if (wpDef && this.textures.exists(wpDef.bgKey)) {
   376→        this.bgImage.setTexture(wpDef.bgKey).setDisplaySize(400, 600).setAlpha(1).clearTint();
   377→      } else {
   378→        // 선택 배경 없음 → 캐릭터 일러스트를 어둡게 처리
   379→        const def = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
   380→        this.bgImage.setTexture(def.illustKey).setDisplaySize(400, 600).setAlpha(0.2);
   381→      }
   382→    }
   383→  }
