   385→  /** 서버 동기화 후 현재 탭을 내용 갱신 */
   386→  private rebuildGrid() {
   387→    this.cardsContainer.removeAll(true);
   388→    this.cardHighlights.clear();
   389→    this.wpHighlights.clear();
   390→    if (this.activeTab === 'character') {
   391→      this.buildCharacterGrid();
   392→    } else {
   393→      this.buildWallpaperGrid();
   394→    }
   395→  }
