   397→  // ── 배경화면 카드 ────────────────────────────────────────────────────────
   398→
   399→  private createWallpaperCard(wp: BackgroundDef, x: number, y: number) {
   400→    const isOwned = this.ownedWpIds.includes(wp.id);
   401→    const isSelected = this.selectedWpId === wp.id;
   402→
   403→    // 카드 배경
   404→    const cardBg = this.add.rectangle(x, y, WP_CARD_W, WP_CARD_H, 0x1a1a2e);
   405→    cardBg.setStrokeStyle(2, isOwned ? WP_ACCENT_INT : 0x333333);
   406→    this.cardsContainer.add(cardBg);
   407→
   408→    // 선택 하이라이트 (흰 테두리)
   409→    const highlight = this.add.rectangle(x, y, WP_CARD_W, WP_CARD_H, 0, 0);
   410→    highlight.setStrokeStyle(3, 0xffffff);
   411→    highlight.setVisible(isSelected);
   412→    this.wpHighlights.set(wp.id, highlight);
   413→    this.cardsContainer.add(highlight);
   414→
   415→    // 세로 이미지 (bgKey) — 카드 상단을 채우는 portrait 썸네일
   416→    if (this.textures.exists(wp.bgKey)) {
   417→      const thumb = this.add.image(x, y - 11, wp.bgKey)
   418→        .setDisplaySize(WP_CARD_W - 4, WP_CARD_H - 22);
   419→      if (!isOwned) { thumb.setTint(0x000000); thumb.setAlpha(0.5); }
   420→      this.cardsContainer.add(thumb);
   421→    }
   422→
   423→    // 미보유 자물쇠
   424→    if (!isOwned) {
   425→      const lock = this.add.text(x, y - 8, '🔒', { fontSize: '20px' }).setOrigin(0.5);
   426→      this.cardsContainer.add(lock);
   427→    }
   428→
   429→    // WP 배지 (우상단)
   430→    const badge = this.add.text(x + WP_CARD_W / 2 - 2, y - WP_CARD_H / 2 + 2, 'WP', {
   431→      fontSize: '9px', color: WP_ACCENT_HEX, fontStyle: 'bold',
   432→      backgroundColor: '#000000cc', padding: { x: 3, y: 1 },
   433→    }).setOrigin(1, 0);
   434→    this.cardsContainer.add(badge);
   435→
   436→    // 하단 반투명 바 + 이름
   437→    const barY = y + WP_CARD_H / 2 - 11;
   438→    const bar = this.add.rectangle(x, barY, WP_CARD_W, 22, 0x000000, 0.75);
   439→    this.cardsContainer.add(bar);
   440→    const nameText = this.add.text(x, barY, wp.name, {
   441→      fontSize: '11px',
   442→      color: isOwned ? WP_ACCENT_HEX : '#444444',
   443→      fontStyle: 'bold',
   444→    }).setOrigin(0.5);
   445→    this.cardsContainer.add(nameText);
   446→
   447→    // 클릭 이벤트
   448→    cardBg.setInteractive({ useHandCursor: isOwned });
   449→    if (isOwned) {
   450→      cardBg.on('pointerover', () => cardBg.setFillStyle(0x252540));
   451→      cardBg.on('pointerout',  () => cardBg.setFillStyle(0x1a1a2e));
   452→    }
   453→    cardBg.on('pointerup', () => {
   454→      if (!this.hasDragged && this.hasPointerDownInScene) this.showWallpaperDetail(wp);
   455→    });
   456→  }
