   558→    closeBtnBg.on('pointerout',  () => closeBtnBg.setFillStyle(0x1a1a1a));
   559→    closeBtnBg.on('pointerup',   () => this.hideCharacterDetail());
   560→    panel.add(closeBtnBg);
