   566→  private applyWallpaper(id: string | null) {
   567→    setSelectedWallpaper(id);
   568→    this.selectedWpId = id;
   569→
   570→    // 하이라이트 갱신
   571→    this.wpHighlights.forEach((rect, wpId) => {
   572→      rect.setVisible(wpId === id);
   573→    });
   574→
   575→    // 헤더 텍스트 갱신
   576→    const def = id ? WALLPAPERS.find(w => w.id === id) : null;
   577→    this.headerNameText
   578→      .setText(`배경: ${def?.name ?? '기본'}`)
   579→      .setColor(id ? WP_ACCENT_HEX : '#888888');
   580→
   581→    // 배경 이미지 즉시 반영
   582→    this.updateBgForTab();
   583→
   584→    this.hideCharacterDetail();
   585→  }
