   587→  private createCharacterCard(char: CharacterDef, x: number, y: number) {
   588→    const isOwned = this.ownedIds.includes(char.id);
   589→    const isSelected = this.selectedId === char.id;
   590→    const gradeColorInt = parseInt(char.gradeColor.replace('#', ''), 16);
   591→
   592→    // 카드 배경
   593→    const cardBg = this.add.rectangle(x, y, CARD_W, CARD_H, 0x222222);
   594→    cardBg.setStrokeStyle(2, isOwned ? gradeColorInt : 0x444444);
   595→    this.cardsContainer.add(cardBg);
   596→
   597→    // 선택 하이라이트
   598→    const highlight = this.add.rectangle(x, y, CARD_W, CARD_H, 0, 0);
   599→    highlight.setStrokeStyle(3, 0xffffff);
   600→    highlight.setVisible(isSelected);
   601→    this.cardHighlights.set(char.id, highlight);
   602→    this.cardsContainer.add(highlight);
   603→
   604→    // 캐릭터 이미지
