   806→      // 일러스트 탭 → 비디오 재생 (가챠와 동일한 fitVideo 방식)
   807→      // active 체크: ✕ 탭 시 패널 파괴 직후 이 핸들러가 동시에 발화하는 경우 방지
   808→      const startVideo = () => {
   809→        if (!illust.active || !videoObj?.active) return;
   810→        videoObj!.setVisible(true);
   811→        videoObj!.play(false);
   812→        this.fitVideoToPanel(videoObj!);
   813→        // 비디오 'play' 이벤트 = 실제 재생 시작 시점 → 그때 일러스트 숨김
