   826→        illust.setVisible(true);
   827→      };
   828→      videoObj.setInteractive({ useHandCursor: true });
   829→      videoObj.on('pointerup', stopVideo);
   830→      videoObj.on('complete', stopVideo);
   831→    }
   832→  }
