   834→  /** GachaScene.fitVideoToCanvas와 동일 — aspect ratio 유지하며 400×600 캔버스에 cover */
   835→  private fitVideoToPanel(vid: Phaser.GameObjects.Video): void {
   836→    const W = 400, H = 600;
   837→    vid.setDisplaySize(W, H);
   838→
   839→    const applyContain = () => {
   840→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   841→      const el: HTMLVideoElement | null = (vid as any).video ?? null;
   842→      const nw = el?.videoWidth  || 0;
   843→      const nh = el?.videoHeight || 0;
   844→      if (nw > 0 && nh > 0) {
   845→        const scale = Math.max(W / nw, H / nh);
   846→        vid.setDisplaySize(Math.round(nw * scale), Math.round(nh * scale));
   847→      }
   848→    };
   849→
   850→    vid.once('play', applyContain);
   851→    this.fitVideoTimers.push(this.time.delayedCall(100, applyContain));
   852→    this.fitVideoTimers.push(this.time.delayedCall(500, applyContain));
   853→  }
   854→
   855→  private hideCharacterDetail(): void {
   856→    // fitVideoToPanel의 pending 타이머 취소
   857→    for (const t of this.fitVideoTimers) t.remove();
   858→    this.fitVideoTimers = [];
   859→
   860→    // 비디오 명시 정지 및 HTMLVideoElement src 해제
   861→    if (this.detailVideo) {
   862→      this.detailVideo.stop();
   863→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   864→      const el: HTMLVideoElement | null = (this.detailVideo as any).video ?? null;
   865→      if (el) { el.src = ''; }
   866→      this.detailVideo = null;
   867→    }
   868→
   869→    this.hideInfoPanel();
   870→    this.detailPanel?.destroy();
   871→    this.detailPanel = null;
   872→  }
